cat > $SP/scripts/human_msgs.py <<'EOF'
import json, sys
path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 1500
with open(path, encoding="utf-8") as f:
    for i, line in enumerate(f):
        try:
            ev = json.loads(line)
        except Exception:
            continue
        if ev.get("type") != "user":
            continue
        if ev.get("isMeta") or ev.get("isSidechain"):
            continue
        msg = ev.get("message", {})
        content = msg.get("content")
        texts = []
        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get("type") == "text":
                    texts.append(c.get("text", ""))
        for t in texts:
            if t.startswith("<system-reminder>") or "tool_use_id" in t:
                continue
            t = t.strip()
            if not t:
                continue
            print(f"--- [line {i}] ---")
            print(t[:maxlen] + ("…" if len(t) > maxlen else ""))
EOF
python3 -I $SP/scripts/human_msgs.py $SP/data/scaffold.jsonl 1200 | head -300

